import { countSentenceBlanks } from './questionQuality.js'

const SOURCE = '英語演習I 2中・平常授業'

const REWRITE_QUESTION_IDS = new Set([
  'reg27-07', 'reg27-08', 'reg27-09', 'reg27-10', 'reg27-11',
  'reg15-07', 'reg15-08', 'reg15-09', 'reg15-10',
  'regplus-06', 'regplus-07', 'regplus-08',
  'regopt4-01', 'regopt4-02', 'regopt4-03', 'regopt4-04', 'regopt4-05',
])

const make = (id, lesson, topic, difficulty, type, data) => ({
  id, lesson, topic, difficulty, type,
  rewrite: REWRITE_QUESTION_IDS.has(id),
  prompt: type === 'reorder' ? '日本語の意味に合うように、語句を並べかえなさい。' : type === 'choice' ? '空所に入る最も適切なものを選びなさい。' : '空所に入る語句を入力しなさい。',
  source: `${SOURCE}・${lesson}`,
  blankCount: countSentenceBlanks(data.sentence || ''),
  ...data,
})

const choice = (id, lesson, topic, difficulty, sentence, choices, answer, explanation, japanese = '') => make(id, lesson, topic, difficulty, 'choice', { sentence, choices, answer, answerLabel: answer, explanation, japanese, translation: japanese })
const fill = (id, lesson, topic, difficulty, sentence, answer, explanation, japanese = '', accepted = [answer], answerLabel = answer) => make(id, lesson, topic, difficulty, 'input', {
  sentence,
  answer,
  accepted,
  answerLabel,
  explanation,
  translation: japanese,
  ...(countSentenceBlanks(sentence) === 0 ? { prompt: '日本語に合う英文を入力しなさい。' } : {}),
  ...(REWRITE_QUESTION_IDS.has(id) ? { prompt: '次の2文が同じ意味になるように、空所に入る語句を入力しなさい。' } : {}),
})
const reorder = (id, lesson, topic, difficulty, japanese, words, answer, explanation) => make(id, lesson, topic, difficulty, 'reorder', { japanese, words, answer, answerLabel: answer, explanation, translation: japanese })
const translateChoice = (id, lesson, topic, difficulty, sentence, answer, explanation, choices) => make(id, lesson, topic, difficulty, 'choice', { prompt: '下線部に注意して、正しい日本語訳を選びなさい。', sentence, choices, answer, answerLabel: answer, explanation })

export const REGULAR_QUESTIONS = [
  // Lesson 27: 助動詞
  fill('reg27-01', 'Lesson 27', '助動詞', 'starter', 'The answer (　　　) (　　　) right.', 'will be', "will は未来のことについての予測を表し、その後ろには動詞の原形が来ます。ここで right は「正しい」で、be right が「正しい状態だ」を表します。主語 the answer に合わせて will is とはせず、will be right とします。", 'その答えは正しいでしょう。'),
  fill('reg27-02', 'Lesson 27', '助動詞', 'starter', 'It is raining heavily. You (　　　) drive carefully.', 'should', "should は「〜したほうがよい」という助言です。It is raining heavily が理由で、carefully は drive のしかたを説明します。助動詞の後ろには原形 drive を置くので、should drive carefully になります。", '雨が激しく降っています。あなたは注意して運転すべきです。'),
  fill('reg27-03', 'Lesson 27', '助動詞', 'standard', 'I asked her some questions, but she (　　　) answer them.', "wouldn't", "but は質問したことと答えなかったことの対比です。wouldn't answer は、過去に「どうしても答えようとしなかった」という拒否を表します。wouldn't の後ろは原形 answer で、wouldn't answered にはしません。", '私は彼女にいくつか質問をしたが、彼女はどうしても答えようとしなかった。'),
  fill('reg27-04', 'Lesson 27', '助動詞', 'starter', 'There (　　　) (　　　) be a famous castle around here.', 'used to', "There is/are は「〜がある」、used to be は「以前は〜があった」です。famous castle が昔この辺りに存在した状態を述べるため used to be が合います。to の後ろは原形 be で、was を直接続けません。", '昔、このあたりには有名な城がありました。'),
  fill('reg27-05', 'Lesson 27', '助動詞', 'standard', 'There were a lot of beautiful flowers in the park. I (　　　) (　　　) taken pictures.', 'should have', "should have + 過去分詞は、過去に「〜しておけばよかった」と振り返る形です。花がたくさんあったのに写真を撮らなかった、という後悔が日本語に表れています。take の過去分詞は taken なので should have taken pictures です。", 'その公園にはたくさんの美しい花があった。写真を撮っておくべきだったなあ。'),
  fill('reg27-06', 'Lesson 27', '助動詞', 'standard', 'He (　　　) (　　　) tired because he played soccer all day yesterday.', 'must be', "must + 原形は、根拠から今のことを「〜に違いない」と推測します。根拠は昨日一日中サッカーをしたこと、推測する現在の状態は tired です。したがって must be tired となり、昨日の状態を推量するなら must have been tired を使います。", '彼は昨日一日中サッカーをしていたので、疲れているに違いない。'),
  fill('reg27-07', 'Lesson 27', '助動詞', 'starter', 'Let\'s sing a song together. (　　　) (　　　) sing a song?', 'Shall we', "Let's sing ... と誘った内容を、Shall we sing ...? と質問の形で言い直しています。Shall we は「一緒に〜しませんか」という誘いです。Shall の後ろに主語 we、その後ろに原形 sing を置きます。", '一緒に歌を歌いましょう。歌を歌いませんか。'),
  fill('reg27-08', 'Lesson 27', '助動詞', 'starter', 'You must not park your car here. (　　　) park your car here.', "Don't", "must not park は強い禁止で、「停めてはいけない」です。Don't park ... も同じ禁止を表す命令文で、Don't の後ろは原形 park です。don't have to park にすると「停める必要はない」となり、禁止ではなくなるので注意します。", 'ここに車を止めてはいけません。ここに車を止めないでください。'),
  fill('reg27-09', 'Lesson 27', '助動詞', 'starter', 'You needn\'t finish it by tomorrow. You (　　　) (　　　) (　　　) finish it by tomorrow.', "don't have to", "needn't は「〜する必要はない」です。同じ意味の don't have to に替えると You don't have to finish it ... となります。have to は助動詞ではなく一般動詞の形なので、否定には don't を使います。", '明日までにそれを終える必要はありません。', ["don't have to", 'do not have to']),
  fill('reg27-10', 'Lesson 27', '助動詞', 'starter', 'Must I do my homework before dinner? (　　　) I (　　　) (　　　) do my homework before dinner?', 'Do ... have to', "Must I ...? は義務を尋ねる言い方で、Do I have to ...? と言い換えられます。文中に主語 I がすでにあるので、空欄に入るのは Do / have / to の3語です。Do I have to と I を二度入れないようにします。", '夕食前に宿題をしなければなりませんか。', ['Do have to'], 'Do ... have to'),
  fill('reg27-11', 'Lesson 27', '助動詞', 'standard', 'You ought not to break your promise. You (　　　) (　　　) your promise.', "shouldn't break", "ought not to break は「約束を破るべきではない」です。should not に言い換えると You shouldn't break your promise. となり、should not の後ろは動詞の原形 break です。shouldn't to break としない点に注意します。", 'あなたは約束を破るべきではありません。'),
  reorder('reg27-12', 'Lesson 27', '助動詞', 'standard', '私たちはまた会うことができるでしょう。', ['we', 'will', 'be', 'able', 'to', 'meet', 'again.'], 'We will be able to meet again.', "未来の「〜できる」は will be able to ... で表します。この語順で we will be able to meet again と並べ、最後に again を置きます。will の後ろに can を重ねることはできないので、will can meet とはしません。"),
  reorder('reg27-13', 'Lesson 27', '助動詞', 'advanced', '彼はオリンピックでメダルを取る可能性が十分にある。', ['He', 'may', 'well', 'win', 'a', 'medal', 'at', 'the', 'Olympics.'], 'He may well win a medal at the Olympics.', "may well + 動詞の原形は「十分ありそうだ／おそらく〜する」という見込みを表します。medal を win する可能性が十分にある、という日本語に合います。well は「上手に」ではなく、ここでは may の可能性を強めています。"),
  reorder('reg27-14', 'Lesson 27', '助動詞', 'advanced', '盗みをするくらいなら、死んだほうがましだ。', ['I', 'would', 'rather', 'die', 'than', 'steal.'], 'I would rather die than steal.', "would rather A than B は「BするよりAしたい／Aするほうがましだ」という選択です。ここでは A が die、B が steal なので「盗むより死ぬほうがまし」となります。rather の後も than の後も動詞の原形を使い、to die / to steal にはしません。"),
  reorder('reg27-15', 'Lesson 27', '助動詞', 'advanced', '君にはその会議に出席することが必要だ。', ['It', 'is', 'necessary', 'that', 'you', 'should', 'attend', 'the', 'meeting.'], 'It is necessary that you should attend the meeting.', "It is necessary that ... は「〜することが必要だ」という形です。that節では主語 you の後ろに should attend を置き、should の後の動詞は原形 attend です。should は省かれる場合もありますが、語群にあるのでここでは使います。"),
  choice('reg27-16', 'Lesson 27', '助動詞', 'starter', 'My brother and I (　　　) often make trips together when we were young.', ['would', 'shall', 'could', 'will'], 'would', "when we were young が過去を示し、often make trips はその頃に何度もした行動を表します。would + 原形は過去の習慣を語るときに使えるため、would make が合います。shall や will は過去の習慣を表しません。"),
  choice('reg27-17', 'Lesson 27', '助動詞', 'starter', '(　　　) I carry your baggage?', ['Shall', 'Will', 'Ought', 'Would'], 'Shall', "Shall I carry ...? は「私が運びましょうか」と話し手が申し出る表現です。荷物を運ぶ人は I なので Shall I が続きます。Would I や Will I は、この申し出を表す決まった形ではありません。"),
  choice('reg27-18', 'Lesson 27', '助動詞', 'starter', '(　　　) you lend me your bicycle?', ['May', 'Must', 'Will', 'Might'], 'Will', "Will you + 動詞は、主語 you が示す相手に「〜してくれますか」と頼む形です。この文の Will you lend me your bicycle? は、you に自転車を貸してほしいという依頼です。自分が借りてもよいか許可を尋ねるなら、May I borrow your bicycle? のように自分を表す I を主語にします。May I lend you ...? なら「私があなたに貸してもよいですか」と貸し手が逆になります。", '私に自転車を貸してくれませんか。'),
  choice('reg27-19', 'Lesson 27', '助動詞', 'standard', "I'm not sure, but she (　　　) come to the party before she caught a cold.", ['should have', 'must have', 'need not have', 'may have'], 'may have', "may have + 過去分詞は、過去に起きたことを「〜したかもしれない」と推測する形です。I'm not sure が確かでないこと、before she caught a cold が出来事の時を示すため may have come になります。come は原形と過去分詞が同じ形です。", '確かなことはわかりませんが、彼女は風邪をひく前にパーティーに来たのかもしれません。'),
  choice('reg27-20', 'Lesson 27', '助動詞', 'standard', "He was in London all week, while the meeting was in Tokyo, so he (　　　) attended it in person.", ['may have', 'should have', 'must have', 'cannot have'], 'cannot have', "cannot have + 過去分詞は、過去のことを「〜したはずがない」と強く推測する形です。会議は東京、彼はその間ずっとロンドンという両立しない情報が根拠です。attend の過去分詞 attended を使うので cannot have attended です。", '会議が東京で開かれていた間、彼はずっとロンドンにいたので、本人が出席したはずがありません。'),
  choice('reg27-21', 'Lesson 27', '助動詞', 'starter', 'I (　　　) invite him to the party if he is interested in it.', ['would often', "don't have to", 'would like to', 'should have'], 'would like to', "would like to + 動詞の原形は「〜したい」という希望を丁寧に表します。if he is interested（彼が興味を持っているなら）という条件のとき、招待したいという気持ちです。to の後ろは原形 invite で、would often は過去の習慣を表すので合いません。"),
  choice('reg27-22', 'Lesson 27', '助動詞', 'standard', 'Look at that dark cloud! It [may / can\'t] rain soon.', ['may', "can't"], 'may', "dark cloud は雨の兆しですが、雨が必ず降るとはまだ言えません。may rain soon なら「もうすぐ雨が降るかもしれない」という可能性になります。can't rain は「雨が降るはずがない」という逆の意味です。"),
  choice('reg27-23', 'Lesson 27', '助動詞', 'standard', 'It is surprising that you [must feel / should feel] that way.', ['must feel', 'should feel'], 'should feel', "It is surprising that ... should ... は、that節の内容を意外に感じている表現です。ここでは「あなたがそのように感じるとは意外だ」という意味で should feel を選びます。must feel にすると「きっとそう感じている」という話し手の推量に変わります。"),
  choice('reg27-24', 'Lesson 27', '助動詞', 'standard', 'It is important that you [should / can] be polite to others.', ['should', 'can'], 'should', "It is important that ... は、重要な行動や求められることを述べる形です。ここでは他人に礼儀正しく接することが求められているので should be が合います。can be は「礼儀正しくできる能力がある」となり、求められる態度という文意からずれます。"),
  choice('reg27-25', 'Lesson 27', '助動詞', 'advanced', 'She knows the movie well. She [must watch / must have watched] it many times.', ['must watch', 'must have watched'], 'must have watched', "She knows the movie well が、何度も見たのだろうと考える根拠です。過去の鑑賞を推測するので must have watched を使います。must watch は「見る必要がある」という義務になり、過去を振り返る推量ではありません。"),
  choice('reg27-26', 'Lesson 27', '助動詞', 'starter', 'He will arrive soon, so you [might as well / as might well] wait for him.', ['might as well', 'as might well'], 'might as well', "彼はもうすぐ着くので、待つのがよさそうだという提案です。might as well + 原形 wait は「そうするのがよさそうだ」という表現です。語順は might as well で、as might well にはしません。"),
  choice('reg27-27', 'Lesson 27', '助動詞', 'starter', 'The bicycle is mine, so you [must / can] use it.', ['must', 'can'], 'can', "この自転車は話し手のものだと分かっているため、相手に使う許可を出しています。can use はここでは「使ってよい」で、能力の「使える」とは違います。must use だと「使わなければならない」という義務になります。"),
  translateChoice('reg27-28', 'Lesson 27', '助動詞', 'starter', 'He could beat my sister at the party.', '彼はパーティーで私の姉（妹）を負かすことができた。', "could + 動詞の原形は過去の能力や可能性を表せます。beat はここでは「打ち負かす」で、my sister がその相手（目的語）です。したがって「彼が姉妹を負かすことができた」となり、姉妹が彼に負かされたという意味ではありません。", ['彼はパーティーで私の姉（妹）を負かすことができた。', '彼はパーティーで私の姉（妹）に負かされた。', '彼はパーティーで私の姉（妹）を負かすべきだった。', '彼はパーティーで私の姉（妹）に会えなかった。']),
  translateChoice('reg27-29', 'Lesson 27', '助動詞', 'standard', 'She may have been very busy last night.', '彼女は昨夜とても忙しかったのかもしれない。', "may have been + 形容詞は、過去の状態について「〜だったかもしれない」と推測します。last night が過去なので、may be（今〜かもしれない）ではなく may have been です。この形が「忙しかった」と断定しない語調も表しています。", ['彼女は昨夜とても忙しかったのかもしれない。', '彼女は昨夜とても忙しくなければならなかった。', '彼女は昨夜とても忙しかったに違いない。', '彼女は昨夜とても忙しいだろう。']),
  translateChoice('reg27-30', 'Lesson 27', '助動詞', 'starter', 'We used to talk with each other about our dreams for the future.', '私たちは以前、将来の夢についてお互いに話したものだ。', "used to talk は以前繰り返していた習慣を表します。with each other は「お互いに」、about our dreams for the future は話したテーマです。used to は「以前は〜したものだ」で、今も必ず続いている意味ではありません。", ['私たちは以前、将来の夢についてお互いに話したものだ。', '私たちは今、将来の夢についてお互いに話している。', '私たちは将来の夢についてお互いに話したい。', '私たちは以前、将来の夢についてお互いに話さなかった。']),
  translateChoice('reg27-31', 'Lesson 27', '助動詞', 'standard', 'I suggest that we start the meeting without him.', '私は彼なしで会議を始めることを提案します。', "suggest that ... は「〜することを提案する」です。ここで提案する内容は「私たちが彼を待たずに会議を始める」なので、that we start と続けます。提案を表すthat節では start の原形を使い、starts にはしません。", ['私は彼なしで会議を始めることを提案します。', '私は彼と一緒に会議を始めることを提案します。', '私は彼なしで会議を終えることを提案しました。', '私は彼なしで会議に出席することを提案します。']),
  fill('reg27-32', 'Lesson 27', '助動詞', 'standard', '彼は一生懸命勉強しなければならなかった。', 'He had to study hard.', "have to は義務を表し、過去形 had to は「〜しなければならなかった」です。主語が he なので had to study hard とします。to の後ろには動詞の原形 study を置き、studied にしません。"),
  fill('reg27-33', 'Lesson 27', '助動詞', 'standard', '彼女は私のことを心配しているに違いない。', 'She must be worried about me.', "must はここでは命令でなく、状況からの強い推測です。be worried about me で「私のことを心配している状態」を表し、about me が心配の対象を示します。must の後ろには原形 be を置くので must be worried です。"),
  fill('reg27-34', 'Lesson 27', '助動詞', 'advanced', '君はそこへ行く必要はなかった。', 'You need not have gone there.', "need not have + 過去分詞は、必要のなかった行為を実際にはした、という意味を基本にします。You need not have gone there なら「そこへ行ったけれど、行く必要はなかった」です。「行く必要がなかったので行かなかった」なら You didn't have to go there / You didn't need to go there と言います。日本語の設問だけでは実際に行ったかどうかは確定しませんが、この英語表現では「行ったが、その必要はなかった」という含みが基本です。", '', ['You need not have gone there.', 'You needn\'t have gone there.']),
  fill('reg27-35', 'Lesson 27', '助動詞', 'advanced', '彼らがそう考えるのも当然だ。', 'It is natural that they should think so.', "It is natural that they should think so は「彼らがそう考えるのは当然だ／自然だ」という判断を述べます。that節の they should think の動詞は原形で、so は「そのように」です。It is natural for them to think so と言い換えても同じ内容を表せます。", '', ['It is natural that they should think so.', 'It is natural for them to think so.']),

  // Lesson 13: 不定詞 (1)
  reorder('reg13-01', 'Lesson 13', '不定詞・名詞的用法', 'starter', '私たちの目的は貧しい人を助けることです。', ['Our', 'purpose', 'is', 'to', 'help', 'the', 'poor.'], 'Our purpose is to help the poor.', "to help the poor は「貧しい人を助けること」で、Our purpose（私たちの目的）の内容を説明しています。be動詞 is の後ろに置かれた to不定詞が、主語の目的を言い表す補語です。help の前に to を付けた形をひとかたまりで並べます。"),
  reorder('reg13-02', 'Lesson 13', '不定詞・名詞的用法', 'starter', '私たちは船で北海道に行くことを計画した。', ['We', 'planned', 'to', 'go', 'to', 'Hokkaido', 'by', 'ship.'], 'We planned to go to Hokkaido by ship.', "planned to go は「行くことを計画した」です。最初の to は plan の後ろに来る to不定詞の一部で、次の to Hokkaido は行き先を示す前置詞です。同じ to でも役割が違うので、We planned to go to Hokkaido と続けます。"),
  reorder('reg13-03', 'Lesson 13', '不定詞・名詞的用法', 'starter', '外国語を習得するのはとても難しい。', ['It', 'is', 'very', 'hard', 'to', 'master', 'a', 'foreign', 'language.'], 'It is very hard to master a foreign language.', "英語では長い内容を文頭に置かず、It is very hard ... で始めることができます。この It は具体的な「それ」を指さない仮主語で、本当の内容は後ろの to master a foreign language（外国語を習得すること）です。to不定詞を文頭に置く To master a foreign language is ... も文法的ですが、この設問の語群は It で始まります。"),
  reorder('reg13-04', 'Lesson 13', '不定詞・名詞的用法', 'standard', 'トムはその木に登ることは容易だとわかった。', ['Tom', 'found', 'it', 'easy', 'to', 'climb', 'the', 'tree.'], 'Tom found it easy to climb the tree.', "Tom found it easy to climb the tree は「木に登るのは簡単だとトムは分かった」です。it は to climb the tree という内容を先に受ける仮の目的語で、easy がその評価を表します。find it + 形容詞 + to do の語順なので、it を抜かしたり easy の後に置いたりしません。"),
  fill('reg13-05', 'Lesson 13', '不定詞・形容詞的用法', 'starter', 'I have a lot of friends (　　　) (　　　) (　　　).', 'to talk with', "friends to talk with は「話し相手になってくれる友達」です。to talk with が friends を後ろから説明し、talk with someone の相手が friends に当たります。そのため前置詞 with を残し、friends to talk とだけでは相手が示されません。", '私は話し相手になってくれる友達がたくさんいます。'),
  fill('reg13-06', 'Lesson 13', '不定詞・形容詞的用法', 'starter', 'Bob bought a book (　　　) (　　　) on the bus.', 'to read', "book to read は「読むための本／読む本」で、to read が直前の book を説明します。read の目的語はこの book なので、後ろに it を重ねません。on the bus はその本を読む場面を添えています。", 'ボブはバスの中で読む本を買いました。'),
  fill('reg13-07', 'Lesson 13', '不定詞・形容詞的用法', 'starter', 'She has the ability (　　　) (　　　) the work.', 'to do', "ability to do は「〜する能力」というまとまりです。to do the work が、どんな能力なのかを具体的に説明します。ability のあとに to不定詞を置く語順を押さえましょう。", '彼女にはその仕事をする能力があります。'),
  fill('reg13-08', 'Lesson 13', '不定詞・形容詞的用法', 'starter', "He's looking for a house (　　　) (　　　) (　　　).", 'to live in', "to live in は house を説明し、「住む家」という意味を作ります。live in a house と考えると、house が前に移り、前置詞 in だけが最後に残った形だと分かります。house がすでにあるので、it を加えて house to live in it とはしません。", '彼は住む家を探しています。'),
  translateChoice('reg13-09', 'Lesson 13', '不定詞・形容詞的用法', 'starter', 'He is not a person to tell a lie.', '彼はうそをつくような人ではありません。', "to tell a lie は直前の a person を説明し、「うそをつくような人」という性質を表しています。文全体は「彼はうそをつくような人ではない」という評価です。ここでの to tell は誰かに「言いなさい」と命じる表現ではありません。", ['彼はうそをつくような人ではありません。', '彼はうそをつく人を知りません。', '彼はうそをつくように言われた人ではありません。', '彼はうそをつかない人だと話しました。']),
  translateChoice('reg13-10', 'Lesson 13', '不定詞・名詞的用法', 'standard', 'To study a language is to know a different culture.', '言語を学ぶことは、異なる文化を知ることです。', "To study a language が文の主語で、「言語を学ぶこと」を表します。be動詞 is の後ろにある to know a different culture は、その主語の内容を説明する補語です。二つの to不定詞をどちらも「〜すること」と読むと、主語と説明部分の関係がつかめます。", ['言語を学ぶことは、異なる文化を知ることです。', '言語を学ぶことは、異なる文化を教えることです。', '異なる文化を知ることは、言語を学ぶことです。', '言語を学んだので、異なる文化を知りました。']),
  translateChoice('reg13-11', 'Lesson 13', '不定詞・名詞的用法', 'starter', 'He decided to join the soccer team.', '彼はサッカーチームに入ることを決めました。', "decided to join は「入ることを決めた」です。join the soccer team が、彼が決めた内容を表しています。decide のあとに to不定詞を続け、joining ではなく to join とするのがこの形です。", ['彼はサッカーチームに入ることを決めました。', '彼はサッカーチームに入ることを忘れました。', '彼はサッカーチームに入るように決められました。', '彼はサッカーチームに入っていると決めました。']),
  translateChoice('reg13-12', 'Lesson 13', '不定詞・形容詞的用法', 'starter', 'I have a lot of homework to hand in next Monday.', '私は来週の月曜日に提出する宿題がたくさんあります。', "to hand in が homework を後ろから説明し、「提出する宿題」という意味になります。hand in は「提出する」という句動詞で、next Monday は提出する日を示しています。homework が hand in の目的語なので、to hand it in のように it を追加しません。", ['私は来週の月曜日に提出する宿題がたくさんあります。', '私は来週の月曜日に提出した宿題がたくさんありました。', '私は来週の月曜日に宿題を提出することを決めました。', '私は来週の月曜日に提出する宿題が一つあります。']),
  translateChoice('reg13-13', 'Lesson 13', '不定詞・形容詞的用法', 'starter', "I'm hungry. I want something to eat.", 'お腹が空きました。何か食べるものが欲しいです。', "something to eat は「食べるもの／何か食べるもの」です。something が eat の目的語に当たり、to eat がその中身を説明しています。最初の文で hungry とあるため、食べ物を求める訳が自然です。", ['お腹が空きました。何か食べるものが欲しいです。', 'お腹が空きました。何かを食べている人が欲しいです。', 'お腹がいっぱいです。何か食べるものが欲しいです。', 'お腹が空きました。何も食べたくありません。']),
  fill('reg13-14', 'Lesson 13', '不定詞・名詞的用法', 'standard', '英語を話すことはとても難しい。', 'It is difficult to speak English.', "この文では It を仮主語にし、to speak English が「英語を話すこと」という本当の主語の内容を表します。It is difficult to ... は「〜するのは難しい」という語順です。To speak English is very difficult と言うこともでき、不定詞を主語の位置に置いています。very は「とても」と難しさを強める語です。", '', ['It is difficult to speak English.', 'To speak English is very difficult.']),

  // Lesson 14: 不定詞 (2)
  translateChoice('reg14-01', 'Lesson 14', '不定詞・副詞的用法', 'standard', 'I went to Harajuku to buy some clothes yesterday.', '私は昨日、服を買うために原宿へ行きました。', "to buy some clothes は、原宿へ行った目的を表します。I went to Harajuku の to は行き先、to buy の to は「〜するために」という不定詞で、同じ形でも働きが違います。yesterday は買いに行った時を示しています。", ['私は昨日、服を買うために原宿へ行きました。', '私は昨日、服を買ったあとで原宿へ行きました。', '私は昨日、服を買うために原宿から帰りました。', '私は昨日、服を買わずに原宿へ行きました。']),
  translateChoice('reg14-02', 'Lesson 14', '不定詞・副詞的用法', 'standard', 'He grew up to be a lawyer.', '彼は成長して弁護士になりました。', "ここでの grow up to be は「成長して、結果として〜になる」です。to be a lawyer は成長する目的ではなく、成長後にたどり着いた結果を表します。後ろに起きた結末が続く to不定詞の使い方です。", ['彼は成長して弁護士になりました。', '彼は弁護士になるために成長しました。', '彼は弁護士を成長させました。', '彼は成長した弁護士に会いました。']),
  translateChoice('reg14-03', 'Lesson 14', '不定詞・副詞的用法', 'standard', 'She is very kind to help them.', '彼女は親切にも彼らを助けてあげました。', "to help them は、彼女が kind（親切）だと評価される理由を示します。つまり、彼女が彼らを助ける行為が「親切だ」という判断につながっています。「助けるために親切だ」という目的の訳にはなりません。", ['彼女は親切にも彼らを助けてあげました。', '彼女は彼らを助けるのを親切に思いました。', '彼女は彼らを助けてもらって親切でした。', '彼女は彼らを助けるほど冷たかった。']),
  translateChoice('reg14-04', 'Lesson 14', '不定詞・副詞的用法', 'standard', 'I was sad to hear the news.', '私はその知らせを聞いて悲しかった。', "sad は感情を表す形容詞で、その後ろの to hear the news が悲しみのきっかけを示します。「知らせを聞いたので悲しかった」という関係です。ここでは「聞くために悲しかった」という目的ではありません。", ['私はその知らせを聞いて悲しかった。', '私はその知らせを聞くと嬉しかった。', '私はその知らせを聞いて驚きました。', '私はその知らせを聞かないで悲しかった。']),
  translateChoice('reg14-05', 'Lesson 14', '不定詞・副詞的用法', 'standard', 'He was very happy to get the job.', '彼はその仕事を得てとても幸せでした。', "仕事を得たことが happy（幸せ）の理由なので、to get the job は感情の原因を表します。happy to do は「〜してうれしい」というまとまりです。get the job は幸せになる目的ではなく、実際に仕事を得たことを指します。", ['彼はその仕事を得てとても幸せでした。', '彼はその仕事を得るためにとても幸せでした。', '彼はその仕事を失ってとても幸せでした。', '彼はその仕事を得た人をとても幸せにしました。']),
  fill('reg14-06', 'Lesson 14', 'SVO + 不定詞', 'standard', 'I (　　　) (　　　) (　　　) (　　　) the role.', 'want him to take', "want + 人 + to do は「人に〜してほしい」という形です。彼が役を演じるので、人を表す him を want のすぐ後ろに置き、その行為を to take the role と続けます。play the role としても「その役を演じる」という意味になります。", '私は彼にその役を演じてほしい。', ['want him to take', 'want him to play']),
  fill('reg14-07', 'Lesson 14', 'SVO + 不定詞', 'standard', 'The police officer (　　　) (　　　) (　　　) (　　　) home.', 'told us to go', "警官が「私たちに帰るよう言った」ので、tell + 人 + to do の形を使います。帰る人は us、指示の内容は to go home です。let us go や made us go とは形も意味も異なり、told us の後には to が必要です。", 'その警官は私たちに家に帰るように言いました。'),
  fill('reg14-08', 'Lesson 14', 'SVO + 不定詞', 'standard', 'My parents (　　　) (　　　) (　　　) (　　　) a telescope.', 'allowed me to use', "allow + 人 + to do は「人が〜することを許す」です。使う許可を得た人が me、許された行為が to use a telescope です。allow me use と to を抜かさないようにします。", '両親は私が望遠鏡を使うのを許してくれました。'),
  fill('reg14-09', 'Lesson 14', 'SVO + 不定詞', 'standard', 'The doctor (　　　) (　　　) (　　　) (　　　) more exercise.', 'advised me to do', "advise + 人 + to do は「人に〜するよう助言する」です。医師の助言を受けたのは me で、その内容が to do more exercise です。ここでは「運動をさせた」ではなく、助言したことを表します。", '医師は私にもっと運動するように助言しました。'),
  reorder('reg14-10', 'Lesson 14', '意味上の主語', 'standard', 'アンがその机を動かすことは困難だった。', ['It', 'was', 'hard', 'for', 'Anne', 'to', 'move', 'the', 'desk.'], 'It was hard for Anne to move the desk.', "It was hard for Anne to move the desk は「アンが机を動かすのは大変だった」です。for Anne が、to move の動作をする人を示します。for の後ろは人の名前、その後ろは to + 動詞の原形という順に並べます。"),
  reorder('reg14-11', 'Lesson 14', '意味上の主語', 'standard', '他人の気持ちを理解するのは簡単ではない。', ['It', 'is', 'not', 'easy', 'to', 'understand', 'others\'','feelings.'], "It is not easy to understand others' feelings.", "文頭の It は具体的なものを指さない仮主語です。本当の評価対象は to understand others' feelings（他人の気持ちを理解すること）で、not easy が「簡単ではない」と述べています。others' は「他人たちの」で、feelings を所有する関係です。"),
  reorder('reg14-12', 'Lesson 14', '意味上の主語', 'standard', 'ドアにかぎをかけないままにしておいたとは、私は不注意だった。', ['I', 'was', 'careless', 'to', 'leave', 'the', 'door', 'unlocked.'], 'I was careless to leave the door unlocked.', "I was careless to leave the door unlocked は「ドアを鍵のかからない状態で放置したのは不注意だった」です。to leave ... が careless と判断する根拠を示します。unlocked は door の状態を表すので、leave the door unlocked で「ドアを鍵のかかっていないままにする」となります。"),
  reorder('reg14-13', 'Lesson 14', '不定詞の否定', 'standard', '私たちはその試合に出場しないことに決めた。', ['We', 'decided', 'not', 'to', 'take', 'part', 'in', 'the', 'game.'], 'We decided not to take part in the game.', "decided not to take part は「参加しないことに決めた」です。不定詞の行為を否定するときは not を to の前に置き、not to take part とします。take part in the game で「その試合に参加する」です。"),
  fill('reg14-14', 'Lesson 14', 'SVO + 不定詞', 'standard', '私は彼女に宿題を手伝ってくれるように頼んだ。', 'I asked her to help me with my homework.', "ask + 人 + to do は「人に〜するよう頼む」です。頼まれた人は her、頼んだ内容は to help me with my homework です。I asked her to help with my homework のように me を省いても、彼女に宿題を手伝うよう頼んだ意味になります。", '', ['I asked her to help me with my homework.', 'I asked her to help with my homework.']),

  // Lesson 15: 不定詞 (3)
  choice('reg15-01', 'Lesson 15', '使役動詞', 'standard', "Maya is out now. I'll [have / let] her call you back when she gets back.", ['have', 'let'], 'have', "I'll have her call you back は「彼女に折り返し電話をしてもらいます」という手配です。have + 人 + 動詞の原形では、電話する人が her、行為が call です。let を使うと電話する許可を与える意味になり、ここでの「戻ったら連絡するよう頼む」とずれます。"),
  choice('reg15-02', 'Lesson 15', '使役動詞', 'standard', "I wanted to go fishing with you, but my father didn't (　　　) me go out.", ['let', 'to let'], 'let', "父親が外出を許さなかったので、didn't let me go out とします。let + 人 + 動詞の原形では、外出する人は me、行為は go out です。let の後ろに to を入れて to go out とはしません。"),
  choice('reg15-03', 'Lesson 15', '使役動詞', 'standard', 'He was [made to go / had to go] to the library with his friends.', ['made to go', 'had to go'], 'made to go', "人に無理に行かされたことを表す受け身なので was made to go が合います。能動態では make + 人 + 原形ですが、受け身になると to が戻り、be made to do になります。had to go は「行く必要があった」という義務で、誰かに行かされた意味とは異なります。"),
  choice('reg15-04', 'Lesson 15', '知覚動詞', 'standard', 'I heard my sister [say / to say] something in her sleep.', ['say', 'to say'], 'say', "hear + 人 + 動詞の原形は、その人の動作を聞いたことを表します。ここでは眠っている間に姉が何か言うのを聞いたので heard my sister say ... です。能動態の知覚動詞の後ろに to say は置きません。"),
  choice('reg15-05', 'Lesson 15', '知覚動詞', 'standard', "I didn't notice Brad [leave / to leave] the house.", ['leave', 'to leave'], 'leave', "notice Brad leave the house は、ブラッドが家を出る動作に気づいたという形です。notice + 人 + 原形では to を付けず leave とします。to leave にすると、この知覚動詞の形から外れます。"),
  choice('reg15-06', 'Lesson 15', '知覚動詞', 'standard', 'The man was seen [enter / to enter] the building.', ['enter', 'to enter'], 'to enter', "能動態なら see + 人 + 原形ですが、ここでは男性を主語にした受け身です。知覚動詞が受け身になると to が必要になり、was seen to enter となります。建物に入る人が主語なので「見られた」と訳します。"),
  fill('reg15-07', 'Lesson 15', 'seem + 不定詞', 'standard', 'It appeared that the gentleman was very rich. The gentleman appeared (　　　) (　　　) very rich.', 'to be', "that節の was very rich を主語 the gentleman を中心に言い換えると appeared to be very rich です。紳士が裕福だという状態と、そう見えた時点は同じなので to be を使います。to have been にすると、裕福だった時期が「そう見えた」時より前という意味になります。", 'その紳士はとても裕福だと思われました。'),
  fill('reg15-08', 'Lesson 15', 'seem + 不定詞', 'standard', 'It seemed Mr. Inoue was looking for something. Mr. Inoue seemed (　　　) (　　　) (　　　) for something.', 'to be looking', "Mr. Inoue seemed to be looking ... は「井上氏は探している最中のようだった」です。探す動作が続いていたことを表すため、seem to be doing の形にします。to look だけでは進行中という情報がなくなります。", '井上氏は何かを探しているようでした。'),
  fill('reg15-09', 'Lesson 15', '完了形の不定詞', 'advanced', 'It seemed that I had left my glasses somewhere. I seemed (　　　) (　　　) (　　　) my glasses somewhere.', 'to have left', "眼鏡を置き忘れたのは、そう思われた時点より前です。その前後関係は to have + 過去分詞で表し、leave の過去分詞 left を使って to have left とします。to leave だけでは、seemed と同時のことのように読めます。", '私はどこかに眼鏡を置き忘れたようでした。'),
  fill('reg15-10', 'Lesson 15', '完了形の不定詞', 'advanced', 'It seems that he was caught in a shower. He seems (　　　) (　　　) (　　　) (　　　) in a shower.', 'to have been caught', "彼が雨にあった出来事は「今そう見える」時点より前なので、to have ... とします。彼は雨に当たった側だから have been caught と受け身にし、全体は to have been caught です。in a shower はここでは「にわか雨にあって」を表します。", '彼はにわか雨にあったようです。'),
  reorder('reg15-11', 'Lesson 15', '完了形の不定詞', 'advanced', '昨夜、私は誰かが大声で叫ぶのを聞いた。', ['I', 'heard', 'someone', 'cry', 'out', 'last', 'night.'], 'I heard someone cry out last night.', "heard someone cry out は「誰かが叫ぶのを聞いた」です。hear + 人 + 原形は叫ぶ一連の動作を聞いたことを示し、cry out が「叫ぶ」です。last night が過去を示すため heard となりますが、後ろの cry は原形のままです。"),
  reorder('reg15-12', 'Lesson 15', 'seem + 不定詞', 'standard', '弟にその場所まで案内させますね。', ['I\'ll', 'have', 'my', 'brother', 'show', 'you', 'the', 'place.'], "I'll have my brother show you the place.", "I'll have my brother show you ... は「弟にあなたを案内させます／案内してもらいます」です。案内する人を my brother、案内する動作を show とし、have + 人 + 原形でつなぎます。使役の have の後ろなので show に to は付けません。"),
  reorder('reg15-13', 'Lesson 15', '完了形の不定詞', 'advanced', '私は彼らのリーダーに選ばれて運がよかった。', ['I', 'was', 'lucky', 'to', 'have', 'been', 'chosen', 'as', 'their', 'leader.'], 'I was lucky to have been chosen as their leader.', "選ばれたのは「幸運だ」と感じた時点より前なので、完了形の不定詞 to have been chosen を使います。I が選ぶ側ではなく選ばれる側なので、have been + 過去分詞の受け身です。as their leader は「彼らのリーダーとして」を添えています。"),
  reorder('reg15-14', 'Lesson 15', '不定詞の受動態', 'advanced', '私はそのパーティーに招待されなくて悲しかった。', ['I', 'was', 'sad', 'not', 'to', 'have', 'been', 'invited', 'to', 'the', 'party.'], 'I was sad not to have been invited to the party.', "招待されなかった出来事が悲しいと感じた時より前なので、to have been invited と完了形にします。I は招待する側ではなく招待される側だから been invited の受け身です。not は「招待された」を否定し、not to have been invited となります。"),
  reorder('reg15-15', 'Lesson 15', '進行形の不定詞', 'standard', 'シンジは今、公園でサッカーをしているようだ。', ['Shinji', 'seems', 'to', 'be', 'playing', 'soccer', 'in', 'the', 'park', 'now.'], 'Shinji seems to be playing soccer in the park now.', "now が示すとおり、サッカーをしている動作は「今」進行中だと推測しています。そのため seem の後ろは to be playing となり、seems to be playing で「しているようだ」です。to play だけでは進行中という意味を表せません。"),
  fill('reg15-16', 'Lesson 15', '使役動詞', 'standard', 'Why didn’t you come to the party yesterday?', 'My father made me do my homework.', "最初の Why didn't you come ...? は会話のきっかけで、空欄に答える対象ではありません。返答の意味は「父が私に宿題をさせた」なので、My father made me do my homework とします。make + 人 + 動詞の原形で、宿題をするのは me です。能動態の make の後ろに to do は置きません。", 'お父さんが私に宿題をさせたんだ。'),

  // Plus: 不定詞
  translateChoice('regplus-01', 'Plus', '不定詞・独立不定詞', 'advanced', 'We happened to know each other.', '私たちはたまたま知り合った。', "happen to + 動詞の原形は「たまたま〜する／〜である」という偶然を表します。ここではお互いを知っていたことが偶然で、意図して知り合ったという意味ではありません。to の後ろに動詞の原形 know を置きます。", ['私たちはたまたま知り合った。', '私たちはお互いを知ろうと努力した。', '私たちは以前からお互いを知っていた。', '私たちはたまたまお互いを避けた。']),
  translateChoice('regplus-02', 'Plus', '不定詞・be to', 'advanced', 'Satoshi came to understand Italian culture while he was in Rome.', 'サトシはローマにいる間に、イタリア文化を理解するようになった。', "came to understand は「だんだん理解するようになった」という変化を表します。Satoshi がローマにいた間にイタリア文化への理解が進んだ、という内容です。ここで come は「来る」ではなく、come to + 動詞で変化を示しています。", ['サトシはローマにいる間に、イタリア文化を理解するようになった。', 'サトシはローマにいる間、イタリア文化を教えるようになった。', 'サトシはローマに行く前にイタリア文化を理解していた。', 'サトシはローマでイタリア文化を理解できなかった。']),
  reorder('regplus-03', 'Plus', '不定詞・be to', 'advanced', 'フランス大統領は来月、日本を訪問する予定です。', ['The', 'French', 'President', 'is', 'to', 'visit', 'Japan', 'next', 'month.'], 'The French President is to visit Japan next month.', "is to visit は be to + 動詞の原形で、決まっている予定を表しています。next month が予定の時期を示し、大統領の訪問という公的な予定に合う読み方です。is があるからといって現在の訪問を述べているわけではありません。"),
  reorder('regplus-04', 'Plus', '不定詞・be to', 'advanced', '空には雲一つ見えなかった。', ['Not', 'a', 'cloud', 'was', 'to', 'be', 'seen', 'in', 'the', 'sky.'], 'Not a cloud was to be seen in the sky.', "was to be seen は「見られる／目に入る」という受け身の形です。Not a cloud が文頭にあり、「雲一つない」ことを強調します。to be seen の be は原形で、seen は see の過去分詞です。"),
  reorder('regplus-05', 'Plus', '不定詞・be to', 'advanced', '外出する前に宿題をしなさい。', ['You', 'are', 'to', 'do', 'your', 'homework', 'before', 'you', 'go', 'out.'], 'You are to do your homework before you go out.', "You are to do ... は、相手に「〜しなさい」と指示する形です。外出する前に宿題を済ませるよう求めており、単に予定を述べているのではありません。be to の後ろには動詞の原形 do が続きます。"),
  fill('regplus-06', 'Plus', '形容詞 + to不定詞', 'standard', 'It is easy to find the shop. The shop is (　　　) (　　　) (　　　).', 'easy to find', "The shop is easy to find は「その店は見つけやすい」です。find の目的語だった the shop を文の主語にしたため、to find の後ろに it をもう一度置きません。easy + to do で「〜しやすい」という主語の性質を表します。", 'その店は見つけやすいです。'),
  fill('regplus-07', 'Plus', '疑問詞 + to不定詞', 'standard', "She didn't know where she should go. She didn't know (　　　) (　　　) go.", 'where to', "where to go は「どこへ行くべきか／行けばよいか」です。She didn't know where she should go の she should を省き、疑問詞 + to不定詞にまとめています。疑問詞 where の後ろに to go と続け、where go にはしません。", '彼女はどこへ行けばよいのかわかりませんでした。'),
  fill('regplus-08', 'Plus', 'too ... to', 'advanced', "The coat was so expensive that Kevin couldn't buy it. The coat was (　　　) (　　　) for Kevin (　　　) buy.", 'too expensive to', "too + 形容詞 + for 人 + to do は「人には〜できないほど…だ」という形です。ここではコートが高すぎて、Kevin には買えませんでした。to buy の目的語は文頭の the coat なので、it を重ねません。", 'そのコートはケビンには高すぎて買えませんでした。'),
  fill('regplus-09', 'Plus', 'so ... as to', 'advanced', 'The man was so kind as (　　　) (　　　) me the way to the station.', 'to show', "so + 形容詞 + as to do は「〜するほど…だ」という意味です。この文では駅への道を教えてくれるほど親切だった、ということなので、自然な日本語では「親切にも道を教えてくれた」と訳せます。as の後ろは to + 動詞の原形となるため、to show を入れます。", 'その男性は親切にも私に駅への道を教えてくれました。'),
  fill('regplus-10', 'Plus', 'enough to', 'advanced', 'He is tall (　　　) (　　　) reach the ceiling.', 'enough to', "tall enough to reach は「手が届くほど背が高い」です。enough は形容詞 tall の後ろに置き、その後に to reach the ceiling と続けます。enough tall の順にはしない点を覚えましょう。", '彼は天井に手が届くほど背が高い。'),
  fill('regplus-11', 'Plus', '独立不定詞', 'advanced', '(　　　) (　　　) (　　　), I\'m not very good at math.', 'To be honest', "To be honest は「正直に言うと」という、文全体にかかる決まった表現です。話し手が自分の意見を率直に述べる前置きで、I'm not very good at math の主語や目的語ではありません。文頭のあとにコンマを置いて区切ります。", '正直に言って、私は数学があまり得意ではありません。'),
  fill('regplus-12', 'Plus', '独立不定詞', 'advanced', 'I don\'t (　　　) (　　　) be an adult.', 'want to', "want to be an adult は「大人になりたい」です。don't が want を否定するので、don't want to be は「大人になりたくない」となります。want not to be とすると「大人でないことを望む」という別の組み立てになります。", '私は大人になりたくありません。'),
  fill('regplus-13', 'Plus', 'so as to', 'advanced', 'Keiko is saving money so (　　　) (　　　) travel all over the world.', 'as to', "so as to + 動詞の原形は「〜するために」という目的を表します。ケイコがお金を貯める目的は、世界中を旅行することです。so の後ろに as to travel と続け、as to の後は原形 travel にします。", 'ケイコは世界中を旅行するためにお金を貯めています。'),
  fill('regplus-14', 'Plus', 'in order to', 'standard', 'I went to the station by taxi in order (　　　) (　　　) miss the train.', 'not to', "in order to は「〜するために」、in order not to は「〜しないために」です。タクシーに乗った目的は、電車に乗り遅れることを避けることです。否定の not は to の前に置き、in order not to miss とします。", '電車に乗り遅れないように、私はタクシーで駅まで行きました。'),
  fill('regplus-15', 'Plus', '疑問詞 + to不定詞', 'advanced', 'Would you (　　　) teaching me how to play the guitar?', 'mind', "Would you mind ...? は「〜していただけますか」と頼む丁寧な表現です。mind は「気にする」という動詞なので、その後ろの行為は teaching のように -ing 形にします。how to play the guitar は「ギターの弾き方」です。", 'ギターの弾き方を教えていただけますか。'),
  fill('regplus-16', 'Plus', '独立不定詞', 'advanced', 'To (　　　) (　　　), you should know yourself.', 'begin with', "To begin with は「まず第一に／まず始めに」という文頭の決まった表現です。後ろの you should know yourself が、最初に勧める内容です。ここでは begin を活用させず、To begin with 全体で導入句として使います。", 'まず第一に、あなたは自分自身を知るべきです。'),

  // Lesson 16: 動名詞 (1)
  fill('reg16-01', 'Lesson 16', '動名詞の働き', 'starter', 'Her job is (　　　) English to children.', 'teaching', "Her job is teaching ... は「彼女の仕事は教えることです」という説明です。teaching English to children が Her job の内容を表す動名詞句です。to children は英語を教える相手を示します。", '彼女の仕事は子どもたちに英語を教えることです。'),
  fill('reg16-02', 'Lesson 16', '動名詞の働き', 'starter', '(　　　) in the park refreshes me.', 'Walking', "Walking in the park（公園を歩くこと）全体が主語です。一つの活動として扱うので、動詞は三人称単数形 refreshes になります。Going for a walk（散歩をすること）と言い換えても、文の主語として使えます。", 'その公園を歩くことは私の気分をさわやかにします。', ['Walking', 'Going for a walk']),
  fill('reg16-03', 'Lesson 16', '動名詞の働き', 'starter', 'I finished (　　　) a letter to Bob last night.', 'writing', "finish の後ろには「終えた作業」を表す動名詞を置きます。手紙を書く作業を終えたので finishing ではなく writing が続き、finish writing a letter となります。last night がその作業の時を示しています。", '私は昨夜、ボブへの手紙を書き終えました。'),
  fill('reg16-04', 'Lesson 16', '動名詞の働き', 'starter', "I'm thinking of (　　　) a new pair of glasses this weekend.", 'buying', "think of の of は前置詞で、前置詞の後ろでは動詞を -ing 形にします。考えていることは新しい眼鏡を買うことなので buying a new pair of glasses です。this weekend は購入を考えている時期です。", '私は今週末、新しい眼鏡を買おうと考えています。'),
  fill('reg16-05', 'Lesson 16', '動名詞の働き', 'starter', "My room needs (　　　), but I don't feel like doing it.", 'cleaning', "need + -ing は「〜される必要がある」という受け身の意味になることがあります。部屋は掃除をする側ではなく、掃除される側なので needs cleaning が合います。needs to be cleaned と言えば、受け身であることをよりはっきり示せます。", '私の部屋は掃除が必要ですが、する気になれません。', ['cleaning', 'to be cleaned']),
  reorder('reg16-06', 'Lesson 16', '動名詞の意味上の主語', 'standard', '彼女は一人で美術館に行くのが好きだ。', ['She', 'likes', 'visiting', 'museums', 'alone.'], 'She likes visiting museums alone.', "likes の目的語として、好きな活動を表す visiting museums が続きます。alone は「一人で」で、美術館に行く様子を補っています。訪れる場所を複数形 museums で一般的な趣味として述べています。"),
  reorder('reg16-07', 'Lesson 16', '動名詞の意味上の主語', 'standard', '彼は、娘が歌手であるのを誇りに思っている。', ['He', 'is', 'proud', 'of', 'his', 'daughter', 'being', 'a', 'singer.'], 'He is proud of his daughter being a singer.', "proud of の of は前置詞なので、後ろは being という動名詞になります。歌手である人は his daughter で、娘が歌手であることを誇りに思っています。娘を He の代わりの目的語にするのではなく、being a singer の意味上の主語として置きます。"),
  reorder('reg16-08', 'Lesson 16', '動名詞の意味上の主語', 'standard', '野菜を食べないことは健康に悪い。', ['Not', 'eating', 'vegetables', 'is', 'bad', 'for', 'your', 'health.'], 'Not eating vegetables is bad for your health.', "動名詞を否定するときは not を -ing の前に置きます。Not eating vegetables 全体が「野菜を食べないこと」という主語で、単数扱いのため is が続きます。not vegetables eating の語順にはしません。"),
  reorder('reg16-09', 'Lesson 16', '動名詞の意味上の主語', 'standard', '私は彼がスーツを着ているのを想像できない。', ['I', 'can\'t', 'imagine', 'him', 'wearing', 'a', 'suit.'], "I can't imagine him wearing a suit.", "imagine の後ろに「誰が何をしているか」を動名詞句で置けます。着る人を him、その動作を wearing a suit と表しています。him は imagine の目的語の位置にあるため、主格の he ではなく目的格になります。"),
  fill('reg16-10', 'Lesson 16', '動名詞・完了形', 'advanced', "He's ashamed of (　　　) (　　　) when he was young. [make mistakes]", 'making mistakes', "ashamed of の of は前置詞なので、その後ろは動名詞です。making mistakes は若いころ間違いを繰り返した経験を表します。having made mistakes とすれば、間違いをした時点が恥じる時点より前だとはっきり示せます。when he was young が間違いをした時期です。", '彼は若いころ、よく間違いをしたことを恥じています。', ['making mistakes', 'having made mistakes']),
  fill('reg16-11', 'Lesson 16', '動名詞・受動態', 'advanced', "I don't like (　　　) (　　　) with him. [compare]", 'being compared', "この設問では be compared（比べられる）の be を -ing 形にして、being compared（比べられること）とします。being + 過去分詞が動名詞の受動態です。with him は文にすでにあるので、空欄には being と compared を入れます。", '私は彼と比べられるのが好きではありません。'),
  fill('reg16-12', 'Lesson 16', '動名詞・完了形', 'advanced', 'I regret (　　　) this shirt. [buy]', 'buying', "regret + -ing は、すでにしたことを後悔する形です。今後買うことではなく、このシャツを買ったことを後悔しています。having bought とすることもでき、買った時点が regret より前だとはっきり示せます。", '私はこのシャツを買ったことを後悔しています。', ['buying', 'having bought']),
  fill('reg16-13', 'Lesson 16', '動名詞', 'standard', '私は友達とサッカーをして楽しんだ。', 'I enjoyed playing soccer with my friends.', "enjoy の後ろには楽しんだ活動を表す動名詞を置き、playing soccer とします。with my friends が一緒にした相手を示しています。I had fun playing soccer with my friends と言い換えても、「友達とサッカーをして楽しんだ」という自然な文です。", '', ['I enjoyed playing soccer with my friends.', 'I had fun playing soccer with my friends.']),

  // Lesson 17: 動名詞 (2)
  fill('reg17-01', 'Lesson 17', '動名詞を使った重要表現', 'standard', 'Wayne is looking (　　　) (　　　) (　　　) to Kochi this summer.', 'forward to going', "look forward to の to は不定詞の印ではなく前置詞です。そのため後ろに動詞を置くときは -ing 形にし、going to Kochi とします。ウェインが楽しみにしているのは、この夏高知へ行くことです。", 'ウェインはこの夏、高知に行くことを楽しみにしています。'),
  fill('reg17-02', 'Lesson 17', '動名詞を使った重要表現', 'standard', 'The heavy rain prevented (　　　) (　　　) (　　　) the mountain.', 'me from climbing', "prevent + 人 + from -ing は「人が〜するのを妨げる」です。登れなかった人は me、妨げられた行為は climbing the mountain です。from の後ろを to climb にしないようにします。", '大雨で私はその山に登れませんでした。'),
  fill('reg17-03', 'Lesson 17', '動名詞を使った重要表現', 'standard', "I'm tired. I don't (　　　) (　　　) (　　　) a book this evening.", 'feel like reading', "feel like + -ing は「〜したい気分だ」です。疲れているので、今夜は本を読みたい気分ではないという流れです。否定の don't は feel にかかり、reading は like の後ろに置きます。", '私は疲れていて、今夜は本を読む気分ではありません。'),
  fill('reg17-04', 'Lesson 17', '動名詞を使った重要表現', 'standard', 'Would you (　　　) (　　　) the window?', 'mind opening', "Would you mind + -ing? は、相手の負担を気づかいながら頼む言い方です。窓を開ける行為を opening the window として、mind の後ろに動名詞で続けます。to open ではなく opening です。", '窓を開けていただけますか。'),
  reorder('reg17-05', 'Lesson 17', '動名詞を使った重要表現', 'standard', '彼は手話を使うことに慣れている。', ['He', 'is', 'used', 'to', 'using', 'sign', 'language.'], 'He is used to using sign language.', "be used to + 名詞 / -ing は「〜に慣れている」です。手話を使うことに慣れているので using sign language となります。以前使っていたという used to use sign language と意味を取り違えないようにします。"),
  reorder('reg17-06', 'Lesson 17', '動名詞を使った重要表現', 'advanced', 'それが本当なのかどうかはわからない。', ['There', 'is', 'no', 'knowing', 'whether', 'it', 'is', 'true', 'or', 'not.'], 'There is no knowing whether it is true or not.', "There is no knowing ... は「〜かどうか分からない／知る方法がない」という表現です。whether it is true or not が、真実かどうかという判断の内容を示します。knowing は is の後ろに置かれた動名詞です。"),
  reorder('reg17-07', 'Lesson 17', '動名詞を使った重要表現', 'advanced', 'これ以上彼と言い争いをしてもむだだ。', ['It', 'is', 'no', 'use', 'arguing', 'with', 'him', 'any', 'longer.'], 'It is no use arguing with him any longer.', "It is no use + -ing は「〜してもむだだ」です。arguing with him が、むだだと判断される行為を表します。any longer が「これ以上」を加えているので、文全体は「これ以上言い争ってもむだだ」となります。"),
  choice('reg17-08', 'Lesson 17', '動名詞と不定詞', 'standard', 'Jonathan decided [not to eat / not eating] late at night.', ['not to eat', 'not eating'], 'not to eat', "decide は決めた内容を to不定詞で続けます。食べないと決めたので、否定の not を to の前に置き not to eat とします。not eating は動名詞の形で、decide の後ろにこの設問が求める形ではありません。"),
  choice('reg17-09', 'Lesson 17', '動名詞と不定詞', 'standard', 'Emma enjoyed [to play / playing] the violin yesterday.', ['to play', 'playing'], 'playing', "enjoy の後ろには楽しんだ活動を動名詞で置きます。昨日バイオリンを弾くことを楽しんだので enjoyed playing です。enjoyed to play とは続けません。"),
  choice('reg17-10', 'Lesson 17', '動名詞と不定詞', 'standard', 'My father gave up [to smoke / smoking] ten years ago.', ['to smoke', 'smoking'], 'smoking', "give up は「やめる」という句動詞で、後ろにやめる行為を -ing 形で置きます。10年前に喫煙をやめたので gave up smoking です。to smoke にすると「吸うために諦めた」のような別のつながりになります。"),
  choice('reg17-11', 'Lesson 17', '動名詞と不定詞', 'standard', 'I hope [to be / being] a professional baseball player in the future.', ['to be', 'being'], 'to be', "hope の後ろには、望んでいる内容を to不定詞で続けます。将来プロ野球選手になる希望なので to be a professional baseball player です。in the future が、まだ実現していない希望だと分かる手がかりです。"),
  fill('reg17-12', 'Lesson 17', '動名詞と不定詞', 'standard', 'Do you remember (　　　) to this place often when you were small? [come]', 'coming', "remember + -ing は、過去にしたことを覚えている意味です。小さいころこの場所に何度も来た経験を尋ねるため coming を使います。remember to come なら「これから来るのを忘れないで」という意味になります。", 'あなたは小さいときにこの場所によく来たのを覚えていますか。'),
  fill('reg17-13', 'Lesson 17', '動名詞と不定詞', 'standard', 'Please remember (　　　) (　　　) me when you arrive at the airport. [call]', 'to call', "remember + to do は、これからすることを忘れないようにする意味です。空港に着いた後で電話するよう頼んでいるので remember to call となります。remember calling にすると、すでに電話した記憶を尋ねることになります。", '空港に着いたら、忘れずに私に電話をかけてください。'),
  fill('reg17-14', 'Lesson 17', '動名詞と不定詞', 'standard', 'She forgot (　　　) her dictionary to school. [bring]', 'bringing', "forget + -ing は、実際にした行為や経験を忘れる意味です。この設問の日本語は「学校に持ってきたことを忘れた」なので、bringing が合います。forget to bring なら「持ってくるのを忘れ、実際には持ってこなかった」という意味になります。", '彼女は辞書を学校に持ってきたことを忘れました。'),
  fill('reg17-15', 'Lesson 17', '動名詞と不定詞', 'standard', "I'll never forget (　　　) hands with the president. [shake]", 'shaking', "I'll never forget + -ing は、過去の大切な経験を決して忘れないという表現です。大統領と握手した経験を指すため shaking hands と続けます。forget to shake hands なら、これから握手することを忘れない、という別の意味です。", '私は大統領と握手したことを決して忘れないでしょう。'),
  fill('reg17-16', 'Lesson 17', '動名詞と不定詞', 'starter', '私は最近テニスを習い始めた。', 'I started playing tennis recently.', "start は -ing 形と to不定詞のどちらも後ろに取れます。tennis を始めたという内容は started playing tennis で表せます。started learning tennis と言えば「テニスを習い始めた」という意味になり、recently が始めた時期を示します。", '', ['I started playing tennis recently.', 'I started learning tennis recently.']),

  // Option 4: 名詞構文・無生物主語
  fill('regopt4-01', 'Option 4', '名詞構文', 'standard', 'Ryota runs fast. Ryota is a (　　　) (　　　).', 'fast runner', "元の文では runs fast と「動詞 + fast」で走り方を表しています。名詞で人の特徴を言うときは a fast runner となり、runner が「走る人」、fast がその人の特徴です。fast は副詞にも形容詞にも同じ形で使われます。", 'リョウタは速く走ります。リョウタは走るのが速い人です。'),
  fill('regopt4-02', 'Option 4', '名詞構文', 'standard', 'I am grateful that you accepted my invitation. I am grateful for (　　　) (　　　) of my invitation.', 'your acceptance', "grateful for の for の後ろを名詞句にし、「あなたが招待を受けてくれたこと」を表します。accept の名詞 acceptance を使えば your acceptance of my invitation です。もう一つの形 your accepting of my invitation では、accepting（受け入れること）を動名詞として使っています。どちらも of my invitation が「私の招待を」を補い、文全体の意味を保ちます。", '私は、あなたが招待を受けてくれたことに感謝しています。', ['your acceptance', 'your accepting']),
  fill('regopt4-03', 'Option 4', '名詞構文', 'standard', 'We had no idea that he was safe. We had no idea of (　　　) (　　　).', 'his safety', "of の後ろには名詞句を置くため、形容詞 safe を名詞 safety に変えます。彼自身を表す his を safety の前に置き、his safety で「彼が無事であること」とします。that he was safe の内容が had no idea の対象です。", '彼が無事だとは思いもしませんでした。'),
  fill('regopt4-04', 'Option 4', '名詞構文', 'standard', 'Sally decided to go to the party. Sally (　　　) (　　　) (　　　) to go to the party.', 'made a decision', "decide to go を名詞を使って言い換えると make a decision to go になります。過去に決めたので make は made にし、a decision が「決定」を表します。to go to the party は、何を決めたのかを後ろから補っています。", 'サリーはパーティーに行くことを決めました。'),
  fill('regopt4-05', 'Option 4', '名詞構文', 'standard', 'He was angry because the train arrived late. He was angry about the (　　　) (　　　) of the train.', 'late arrival', "arrive（到着する）を名詞にすると arrival（到着）です。遅れて到着したことを late arrival（遅い到着）と表し、of the train で「列車の到着」だと示します。about の後ろには名詞句が必要なので、動詞 arrived のままではなく名詞 arrival を使います。", '彼は電車が遅れて到着したことに腹を立てていました。'),
  reorder('regopt4-06', 'Option 4', '無生物主語', 'standard', 'その話を聞いて、彼女は自分の考え方を変えた。', ['The', 'story', 'made', 'her', 'change', 'her', 'way', 'of', 'thinking.'], 'The story made her change her way of thinking.', "make + 人 + 動詞の原形は「人に〜させる」です。The story がきっかけとなって、her が change her way of thinking（考え方を変える）という関係です。make の後ろに to change とはせず、原形 change を置きます。"),
  reorder('regopt4-07', 'Option 4', '無生物主語', 'standard', '祖父は医師の助言のおかげで、病気から回復することができた。', ['The', 'doctor\'s', 'advice', 'enabled', 'my', 'grandfather', 'to', 'recover', 'from', 'his', 'illness.'], "The doctor's advice enabled my grandfather to recover from his illness.", "enable + 人 + to do は「人が〜できるようにする」です。医師の助言が回復を可能にし、実際に回復するのは my grandfather です。from his illness は、何から回復するのかを示しています。"),
  reorder('regopt4-08', 'Option 4', '無生物主語', 'standard', '私はプライドのせいで、友だちに助けを求めることができなかった。', ['My', 'pride', 'kept', 'me', 'from', 'asking', 'my', 'friends', 'for', 'help.'], 'My pride kept me from asking my friends for help.', "keep + 人 + from -ing は、その人が何かをするのを妨げる形です。ここでは My pride（プライド）が原因、me が妨げられる人、asking my friends for help ができなかった行為です。from の後ろは asking のように -ing にします。"),
  reorder('regopt4-09', 'Option 4', '無生物主語', 'standard', '事故のせいで、私たちは時間どおりに駅に到着できなかった。', ['The', 'accident', 'prevented', 'us', 'from', 'arriving', 'at', 'the', 'station', 'on', 'time.'], 'The accident prevented us from arriving at the station on time.', "prevent + 人 + from -ing は「人が〜するのを妨げる」です。事故が原因で、us が時間どおりに駅へ着くことができませんでした。arrive は from の後ろなので arriving となり、on time が「時間どおりに」を表します。"),
  reorder('regopt4-10', 'Option 4', '無生物主語', 'standard', '彼の手紙には、彼が4月に私たちを訪れると書いてあった。', ['His', 'letter', 'said', 'that', 'he', 'would', 'visit', 'us', 'in', 'April.'], 'His letter said that he would visit us in April.', "英語では手紙を主語にして His letter said that ...（手紙には〜と書いてあった）と言えます。that節が手紙に書かれていた内容で、he would visit us が「彼が私たちを訪ねる」という予定です。said より後の予定なので will ではなく would になります。"),
  translateChoice('regopt4-11', 'Option 4', '名詞構文', 'starter', 'Let me have a look at that.', 'それをちょっと見せてください。', "have a look at that は「それをちょっと見る」です。Let me は「私に〜させてください」で、let + 人 + 動詞の原形の形なので have が続きます。話し手が見たいと頼んでいるので、「私に見せてください」という訳が選ばれます。", ['それをちょっと見せてください。', 'それを少し聞かせてください。', 'それをちょっと貸してください。', 'それをもう一度説明してください。']),
  translateChoice('regopt4-12', 'Option 4', '名詞構文', 'starter', 'My sister is an early riser.', '私の姉（妹）は早起きです。', "riser は「起きる人」で、early riser は「早起きする人」です。My sister is an early riser は、姉または妹が早く起きる人だという習慣を述べています。early が「早い時間に」を表し、走る速さの話ではありません。", ['私の姉（妹）は早起きです。', '私の姉（妹）は夜更かしです。', '私の姉（妹）は早く走ります。', '私の姉（妹）は朝食を作ります。']),
  translateChoice('regopt4-13', 'Option 4', '無生物主語', 'standard', 'The Internet allows us to get a lot of information.', 'インターネットのおかげで、私たちは多くの情報を得ることができます。', "allow + 人 + to do は「人が〜できるようにする／許す」です。情報を得るのは us、できるようにするものが The Internet です。英語ではインターネットが主語ですが、日本語では「インターネットのおかげで」とすると自然です。", ['インターネットのおかげで、私たちは多くの情報を得ることができます。', 'インターネットのおかげで、私たちは多くの情報を失います。', 'インターネットは私たちに多くの情報を教えることを許しません。', '私たちはインターネットを使わずに多くの情報を得られます。']),
  translateChoice('regopt4-14', 'Option 4', '無生物主語', 'standard', 'The typhoon stopped us from going fishing in the sea.', '台風のため、私たちは海へ釣りに行けませんでした。', "stop + 人 + from -ing は「人が〜するのを止める／妨げる」です。台風のため、私たちが海へ釣りに行く行為ができませんでした。going fishing が止められた行為で、台風が行くよう促したという意味ではありません。", ['台風のため、私たちは海へ釣りに行けませんでした。', '台風のおかげで、私たちは海へ釣りに行きました。', '台風のため、私たちは海で釣りを楽しみました。', '台風は私たちに海へ釣りに行くよう促しました。']),
  translateChoice('regopt4-15', 'Option 4', '無生物主語', 'starter', 'Will this bus take us to the airport?', 'このバスで空港へ行けますか。', "take + 人 + to 場所 は「人を場所まで運ぶ・連れて行く」です。ここでは this bus が us を空港へ運ぶかどうかを尋ねています。Will は未来のことを尋ねる助動詞で、bus の能力というより路線・行き先を確認する質問です。", ['このバスで空港へ行けますか。', 'このバスは空港から来ますか。', 'このバスで空港へ行く人を見ましたか。', 'このバスは空港へ行かずに停まりますか。']),

  // Option 7: 前置詞
  fill('regopt7-01', 'Option 7', 'at / in / on', 'starter', 'Please pick me up (　　　) the station.', 'at', "pick me up は「私を車などで迎えに来る」という句動詞です。迎えに来てもらう場所を一点として示すので at the station とします。代名詞 me は pick と up の間に置きます。", '駅で私を拾ってください。'),
  fill('regopt7-02', 'Option 7', 'at / in / on', 'starter', 'This library closes (　　　) 9 o\'clock.', 'at', "時計で示す正確な時刻には at を使います。9 o'clock は閉館する時刻そのものなので closes at 9 o'clock です。月や年のような幅のある期間に使う in とは区別します。", 'この図書館は9時に閉まります。'),
  fill('regopt7-03', 'Option 7', 'at / in / on', 'starter', 'My sister was born (　　　) July 20th.', 'on', "on は曜日や具体的な日付の前に置きます。July 20th は「7月20日」という一日を指すため was born on July 20th です。July だけなら月なので in July となります。", '私の姉（妹）は7月20日に生まれました。'),
  fill('regopt7-04', 'Option 7', 'at / in / on', 'starter', 'Sarah and Tom are going to get married (　　　) June.', 'in', "June は日付ではなく「6月」という期間なので in を使います。結婚する日は月の中の一点ではなく、月単位で述べられています。June 5th のように具体的な日まで言う場合は on になります。", 'サラとトムは6月に結婚する予定です。'),
  fill('regopt7-05', 'Option 7', 'at / in / on', 'starter', 'I put up a new clock (　　　) the wall (　　　) my room.', 'on in', "時計は壁の表面に掛けるので on the wall、部屋という空間の中にあるので in my room です。二つの空欄は順に on、in となります。面に接している位置と、囲まれた空間の内側を分けて考えます。", '私は部屋の壁に新しい時計を掛けました。', ['on in'], 'on ... in'),
  choice('regopt7-06', 'Option 7', 'from / to / for', 'starter', 'The restaurant is open [from / to] 11 a.m. [from / to] 11 p.m.', ['from ... to', 'to ... from'], 'from ... to', "from A to B は「AからBまで」で、始点のあとに終点を置きます。営業時間は午前11時に始まり、午後11時に終わるため from 11 a.m. to 11 p.m. です。to と from を逆にすると時間の流れに合いません。"),
  choice('regopt7-07', 'Option 7', 'from / to / for', 'starter', 'I visited my grandparents [during / for] the winter vacation.', ['during', 'for'], 'during', "during the winter vacation は「冬休みの間に」です。during の後ろには the winter vacation のように期間を表す名詞句を置きます。for は期間の長さを表すので、ここでの「休みの間に」とは使い分けます。"),
  choice('regopt7-08', 'Option 7', 'from / to / for', 'starter', 'I stayed in Hong Kong [in / for] a week.', ['in', 'for'], 'for', "for a week は「一週間のあいだ」で、滞在が続いた長さを表します。in a week は文脈によって「一週間後に」など、基準時からの時間を表します。香港にいた期間を言うこの文では for が合います。"),
  choice('regopt7-09', 'Option 7', 'from / to / for', 'starter', 'The train [for / to] Atami will depart [in / for] five minutes.', ['for ... in', 'to ... for'], 'for ... in', "for Atami は「熱海行き」で、列車の目的地を示します。in five minutes は「今から5分後に」で、出発までの時間です。二つの前置詞は目的地と時間をそれぞれ示しています。"),
  reorder('regopt7-10', 'Option 7', '前置詞の使い分け', 'standard', '彼女の最新アルバムの題名を知っていますか。', ['Do', 'you', 'know', 'the', 'title', 'of', 'her', 'latest', 'album?'], 'Do you know the title of her latest album?', "Do you know ...? は「〜を知っていますか」という疑問文で、Do の後ろに主語 you、その後ろに動詞 know を置きます。the title of her latest album は「彼女の最新アルバムの題名」です。of が題名とアルバムをつなぎ、her latest が album を説明します。"),
  reorder('regopt7-11', 'Option 7', '前置詞の使い分け', 'standard', '私たちは校庭から雪を取り除いた。', ['We', 'cleared', 'the', 'schoolyard', 'of', 'snow.'], 'We cleared the schoolyard of snow.', "clear A of B は「AからBを取り除く」です。取り除く場所が the schoolyard、取り除かれるものが snow なので、この順で並べます。of snow は雪が校庭からなくなったことを示します。"),
  reorder('regopt7-12', 'Option 7', '前置詞の使い分け', 'starter', 'その犬は玄関のそばに座っていた。', ['The', 'dog', 'was', 'sitting', 'by', 'the', 'front', 'door.'], 'The dog was sitting by the front door.', "by the front door は「玄関のそばに」という位置を表します。was sitting は過去のある時点で座っていた状態で、by the front door がその場所です。by は「〜のそばに」で、前置詞の後ろには場所を示す名詞句が続きます。"),
  reorder('regopt7-13', 'Option 7', '前置詞の使い分け', 'standard', '私は昨日、ショッピングモールで先生が家族といるのを見た。', ['I', 'saw', 'my', 'teacher', 'with', 'his', 'family', 'at', 'the', 'mall', 'yesterday.'], 'I saw my teacher with his family at the mall yesterday.', "with his family は先生が家族を伴っていたこと、at the mall は見かけた場所を示します。yesterday はその出来事があった時です。with を場所、at を同伴者の意味に取り違えないよう、どの語句にかかるかで判断します。"),
  choice('regopt7-14', 'Option 7', '前置詞の使い分け', 'starter', 'I will finish my report [by / until] four, so please wait [by / until] then.', ['by ... until', 'until ... by'], 'by ... until', "by four は「4時までに終える」という完了期限です。一方、until then は「その時までずっと待つ」で、動作が続く終点を表します。終わる期限の finish には by、続ける wait には until が合います。"),
  choice('regopt7-15', 'Option 7', '前置詞の使い分け', 'starter', 'I drew the picture [by / with] a ball-point pen.', ['by', 'with'], 'with', "with a ball-point pen は「ボールペンを使って」で、絵を描く道具を示します。with は手に取って使う道具の前に置きます。by は受け身で動作主を示すときなどに使い、ここでは道具を表しません。"),
  choice('regopt7-16', 'Option 7', '前置詞の使い分け', 'starter', 'I usually go to school [by / with] bike.', ['by', 'with'], 'by', "交通手段は by + 乗り物で表し、by bike のように冠詞を付けません。I usually go to school が普段の通学方法を述べています。with a bike は「自転車を伴って」という意味になるため、交通手段の表現とは異なります。"),
]
